public final class GoetiaPortTests {
 private static final class CombatVictim extends FakePlayer {
  CombatVictim(net.minecraft.server.level.ServerLevel level){super(level,new GameProfile(UUID.randomUUID(),"GoetiaVictim"));setGameMode(GameType.SURVIVAL);setPermanentlyInvulnerable(false);setNoGravity(true);connection.markClientLoaded();}
  @Override public boolean canHarmPlayer(net.minecraft.world.entity.player.Player other){return level().isPvpAllowed();}
 }
 private static FakePlayer player(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.randomUUID(),"GoetiaTest"));p.setGameMode(GameType.SURVIVAL);var at=h.absolutePos(new BlockPos(3,2,3));p.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);p.getInventory().clearContent();p.getPersistentData().remove("goetia");return p;}
 public static void alignmentAndDeathKeepReleasedRules(GameTestHelper h){var p=player(h);h.assertTrue(GoetiaPlayer.lean(p)==GoetiaPlayer.Alignment.ANGEL&&GoetiaPlayer.alignment(p)==GoetiaPlayer.Alignment.HUMAN,"zero alignment leans angel");GoetiaPlayer.set(p,"impurity",2000);GoetiaPlayer.set(p,"purity",1000);h.assertTrue(GoetiaPlayer.alignment(p)==GoetiaPlayer.Alignment.ANGEL&&GoetiaPlayer.lean(p)==GoetiaPlayer.Alignment.DEMON,"purity wins full alignment, impurity wins lean");GoetiaPlayer.data(p).putBoolean("locked",true);GoetiaPlayer.add(p,"impurity",4,false);h.assertTrue(GoetiaPlayer.data(p).getIntOr("impurity",0)==2000,"lock blocks ordinary add");GoetiaPlayer.add(p,"impurity",4,true);h.assertTrue(GoetiaPlayer.data(p).getIntOr("impurity",0)==2004,"regardless bypasses lock");GoetiaPlayer.learn(p,"impSymbol");var next=player(h);GoetiaPlayer.cloneDeath(p,next);h.assertTrue(GoetiaPlayer.data(next).getIntOr("impurity",0)==2004&&GoetiaPlayer.data(next).getIntOr("purity",0)==0&&!GoetiaPlayer.data(next).getBooleanOr("locked",false)&&GoetiaPlayer.knowledge(next).contains("impSymbol"),"death retains only impurity and knowledge");h.succeed();}
 public static void spellThresholdsAndFlightQuirk(GameTestHelper h){var p=player(h);h.assertTrue(GoetiaSpells.ALL.size()==13,"all thirteen released spells");h.assertTrue(GoetiaSpells.ALL.get(0).cost()==30&&java.util.Arrays.equals(GoetiaSpells.ALL.get(0).shape(),new int[]{1,6,3,4}),"burning touch gesture and threshold");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(GoetiaContent.item("soul_focus")));GoetiaPlayer.set(p,"impurity",29);h.assertTrue(!GoetiaSpells.cast(p,"burningTouch"),"below threshold refused");GoetiaPlayer.set(p,"impurity",30);h.assertTrue(GoetiaSpells.cast(p,"burningTouch")&&GoetiaPlayer.data(p).getIntOr("burning_touch",0)==600&&GoetiaPlayer.data(p).getIntOr("impurity",0)==30,"cast does not spend alignment");GoetiaPlayer.set(p,"impurity",196);h.assertTrue(GoetiaSpells.cast(p,"ebonWings")&&p.getAbilities().mayfly,"wings grant flight");for(int i=0;i<1800;i++)GoetiaPlayer.tick(p);h.assertTrue(!GoetiaPlayer.data(p).contains("wings_tag")&&p.getAbilities().mayfly,"released flight remains after visual timer expires");h.succeed();}
 public static void symbolNeedsExtraXpAndCharges101Ticks(GameTestHelper h){var p=player(h);var s=GoetiaEntities.SYMBOLS.get(0).get().create(h.getLevel(),net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);var at=h.absolutePos(new BlockPos(3,2,3));for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)h.getLevel().setBlockAndUpdate(at.offset(x,-1,z),Blocks.STONE.defaultBlockState());s.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);s.setNoAi(true);s.setNoGravity(true);p.experienceLevel=5;h.assertTrue(!s.activate(p),"equal XP cost is refused");p.experienceLevel=6;h.assertTrue(s.activate(p)&&p.experienceLevel==1,"one extra XP level activates");for(int i=0;i<100;i++)s.tick();h.assertTrue(s.ready()<1,"float charge still below one after100");s.tick();h.assertTrue(s.ready()>1&&s.fade()<1,"101st charge completes and starts fade same tick");var imps=h.getLevel().getEntitiesOfClass(GoetiaDemon.class,s.getBoundingBox().inflate(2),e->e.kind==0);h.assertTrue(imps.size()==1,"one imp summoned");for(var d:imps)d.discard();s.discard();h.succeed();}
 public static void forgeConsumesWholeStackAndAllDemons(GameTestHelper h){var w=h.getLevel();var s=GoetiaEntities.SYMBOLS.get(4).get().create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);var at=h.absolutePos(new BlockPos(3,3,3));s.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);var ds=new java.util.ArrayList<GoetiaDemon>();for(int i=0;i<3;i++){var d=GoetiaEntities.DEMONS.get(2).get().create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);d.setPos(s.getX()+i,s.getY(),s.getZ());d.setNoAi(true);w.addFreshEntity(d);ds.add(d);}var input=new ItemEntity(w,s.getX(),s.getY()+1,s.getZ(),new ItemStack(GoetiaContent.item("demon_horn"),4));w.addFreshEntity(input);h.assertTrue(s.forge(),"three demons always exceed value45");h.assertTrue(input.isRemoved()&&ds.stream().allMatch(GoetiaDemon::isRemoved),"entire input stack and all demons removed");var results=w.getEntitiesOfClass(ItemEntity.class,s.getBoundingBox().inflate(3),e->GoetiaContent.is(e.getItem(),"demon_horn_spear"));h.assertTrue(results.size()==1&&results.get(0).getItem().getCount()==1,"one spear result");for(var e:results)e.discard();h.succeed();}
 public static void cleanseWinsOverBloodSummoning(GameTestHelper h){var w=h.getLevel();var p=player(h);var at=h.absolutePos(new BlockPos(3,2,3));w.setBlockAndUpdate(at,GoetiaContent.block("altar").defaultBlockState());w.setBlockAndUpdate(at.above(),GoetiaContent.block("full_bowl").defaultBlockState());var bowl=(GoetiaBlockData)w.getBlockEntity(at.above());bowl.entity="minecraft:cow";w.setBlockAndUpdate(at.above().north(),GoetiaContent.block("angel_candle_stand").defaultBlockState());w.setBlockAndUpdate(at.above().south(),GoetiaContent.block("demon_candle_stand").defaultBlockState());GoetiaPlayer.set(p,"impurity",500);GoetiaPlayer.data(p).putBoolean("locked",true);h.assertTrue(GoetiaRituals.perform(w,at,p),"cleanse matches");h.assertTrue(GoetiaPlayer.data(p).getIntOr("impurity",0)==0&&GoetiaPlayer.data(p).getBooleanOr("locked",false)&&w.getBlockState(at.above()).is(GoetiaContent.block("full_bowl")),"cleanse resets alignment but leaves lock and bowl");w.removeBlock(at.above().north(),false);h.assertTrue(GoetiaRituals.perform(w,at,p)&&w.getBlockState(at.above()).is(GoetiaContent.block("empty_bowl")),"blood summon consumes bowl contents");h.succeed();}
 public static void demonsAndHolyWaterKeepTheirAttributes(GameTestHelper h){for(int i=0;i<3;i++){var d=GoetiaEntities.DEMONS.get(i).get().create(h.getLevel(),net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);h.assertTrue(d.getMaxHealth()==new float[]{28,52,92}[i]&&d.fireImmune(),"released demon health and fire immunity");d.holyWater();h.assertTrue(!d.fireImmune()&&d.isOnFire(),"holy water disables immunity before fire");d.trap();var tag=saveEntity(d);var copy=GoetiaEntities.DEMONS.get(i).get().create(h.getLevel(),net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);loadEntity(copy,tag);h.assertTrue(copy.trapped(),"trap state saves");}h.succeed();}
 public static void voraciousDamageRunsAfterCooldownAndBeforeArmor(GameTestHelper h){var p=player(h);var cow=net.minecraft.world.entity.EntityTypes.COW.create(h.getLevel(),net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);cow.setPos(p.getX(),p.getY(),p.getZ()+2);cow.setNoAi(true);GoetiaPlayer.data(p).putInt("voracious_strikes",300);cow.hurtServer(h.getLevel(),p.damageSources().playerAttack(p),8);h.assertTrue(Math.abs(cow.getHealth()-(cow.getMaxHealth()-2))<.01&&cow.damageCooldownTime==0,"voracious final damage2 and invulnerability0; health="+cow.getHealth()+" invulnerability="+cow.damageCooldownTime);cow.setHealth(cow.getMaxHealth());GoetiaPlayer.data(p).putInt("inner_fire_grace",2400);cow.hurtServer(h.getLevel(),p.damageSources().playerAttack(p),8);h.assertTrue(Math.abs(cow.getHealth()-(cow.getMaxHealth()-2.8f))<.01&&cow.damageCooldownTime==0,"combined voracious and inner damage2.8");var victim=new CombatVictim(h.getLevel());victim.setPos(p.getX()+2,p.getY(),p.getZ());var playerSource=p.damageSources().playerAttack(p);h.assertTrue(victim.connection.hasClientLoaded()&&victim.level().isPvpAllowed()&&!victim.isInvulnerableTo(h.getLevel(),playerSource),"player damage fixture is loaded, PvP-enabled and vulnerable");victim.setHealth(victim.getMaxHealth());victim.damageCooldownTime=0;victim.hurtServer(h.getLevel(),playerSource,8);h.assertTrue(Math.abs(victim.getHealth()-(victim.getMaxHealth()-2.8f))<.01&&victim.damageCooldownTime==0,"player damage path preserves Voracious+Inner amount and final cooldown: health="+victim.getHealth()+" cooldown="+victim.damageCooldownTime);h.succeed();}
 public static void innerFireDoesNotChangeCooldownSelection(GameTestHelper h){var p=player(h);var cow=net.minecraft.world.entity.EntityTypes.COW.create(h.getLevel(),net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);cow.setNoAi(true);cow.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MAX_HEALTH).setBaseValue(40);cow.setHealth(40);cow.hurtServer(h.getLevel(),p.damageSources().playerAttack(p),10);float after=cow.getHealth();h.assertTrue(cow.isAlive()&&Math.abs(after-30)<.01&&cow.damageCooldownTime>10,"first hit establishes a live cooldown window");GoetiaPlayer.data(p).putInt("inner_fire_grace",2400);GoetiaPlayer.data(p).putInt("voracious_strikes",300);boolean accepted=cow.hurtServer(h.getLevel(),p.damageSources().playerAttack(p),8);h.assertTrue(!accepted&&cow.getHealth()==after&&cow.damageCooldownTime>10,"smaller raw hit keeps native rejection and cooldown before modifiers");GoetiaPlayer.data(p).remove("voracious_strikes");cow.damageCooldownTime=0;cow.hurtServer(h.getLevel(),p.damageSources().playerAttack(p),8);h.assertTrue(Math.abs(cow.getHealth()-(after-11.2f))<.01,"accepted hit gets1.4 multiplier before armor");h.succeed();}

 public static void fireballKeepsFixedLegacyAcceleration(GameTestHelper h){
  var p=player(h);var w=h.getLevel();var at=h.absolutePos(new BlockPos(3,6,3));var dir=new net.minecraft.world.phys.Vec3(1,.25,.4);
  var f=new net.minecraft.world.entity.projectile.hurtingprojectile.LargeFireball(w,p,dir,1);f.setOwner(null);f.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);GoetiaFireballs.start(f,dir);h.assertTrue(f.getOwner()==null,"released shot starts without owner");
  var expected=f.position();var velocity=net.minecraft.world.phys.Vec3.ZERO;var power=GoetiaFireballs.normalize(dir).scale(.1);
  for(int i=0;i<5;i++){expected=expected.add(velocity);velocity=velocity.add(power).scale((double).95F);f.tick();h.assertTrue(f.position().distanceTo(expected)<1e-8&&f.getDeltaMovement().distanceTo(velocity)<1e-8,"legacy position/acceleration tick"+i);}
  f.setDeltaMovement(0,.2,0);var expectedOffAxis=new net.minecraft.world.phys.Vec3(0,.2,0).add(power).scale((double).95F);f.tick();h.assertTrue(f.getDeltaMovement().distanceTo(expectedOffAxis)<1e-8,"acceleration stays fixed after off-axis motion");
  var saved=saveEntity(f);var copy=net.minecraft.world.entity.EntityTypes.FIREBALL.create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);loadEntity(copy,saved);h.assertTrue(((LegacyFireballFlight)copy).goetia$power().distanceTo(power)<1e-8&&copy.getOwner()==null,"fixed acceleration saves without retaining an owner");
  boolean punch=f.hurtServer(h.getLevel(),p.damageSources().playerAttack(p),1);h.assertTrue(punch&&f.getDeltaMovement().distanceTo(p.getLookAngle())<1e-8&&f.getOwner()==p,"punch redirects velocity and ownership: accepted="+punch+" actual="+f.getDeltaMovement()+" expected="+p.getLookAngle()+" owner="+f.getOwner());
  f.deflect(net.minecraft.world.entity.projectile.ProjectileDeflection.AIM_DEFLECT,p,net.minecraft.world.entity.EntityReference.of(p),true,1.0);h.assertTrue(f.getDeltaMovement().distanceTo(p.getLookAngle())<1e-8&&((LegacyFireballFlight)f).goetia$power().distanceTo(p.getLookAngle().scale(.1))<1e-8,"real player deflection path resets fixed power");var vanilla=net.minecraft.world.entity.EntityTypes.FIREBALL.create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);h.assertTrue(!((LegacyFireballFlight)vanilla).goetia$hasFlight(),"ordinary fireballs are outside adapter");h.succeed();
 }
 public static void bloodKnifeProducesOneTypedBottle(GameTestHelper h){
  var p=player(h);p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(GoetiaContent.item("blood_knife")));p.getInventory().setItem(1,new ItemStack(Items.GLASS_BOTTLE,2));var cow=net.minecraft.world.entity.EntityTypes.COW.create(h.getLevel(),net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);cow.setNoAi(true);cow.hurtServer(h.getLevel(),p.damageSources().playerAttack(p),100);
  int blood=0,glass=0;for(var stack:p.getInventory().getNonEquipmentItems()){if(stack.is(Items.GLASS_BOTTLE))glass+=stack.getCount();if(GoetiaContent.is(stack,"liquid_bottle")){blood+=stack.getCount();h.assertTrue(GoetiaItem.tag(stack).getStringOr("entityName","").equals("minecraft:cow"),"blood stores killed entity");}}
  h.assertTrue(blood==1&&glass==1,"one kill consumes one bottle and produces one blood");h.succeed();
 }
public static void holyWaterUsesRealWaterAndBreathingPaths(GameTestHelper h) {
 var w=h.getLevel();
 for(int x=2;x<=4;x++)for(int z=2;z<=4;z++){
  w.setBlockAndUpdate(h.absolutePos(new BlockPos(x,0,z)),Blocks.STONE.defaultBlockState());
  for(int y=1;y<=4;y++)w.setBlockAndUpdate(h.absolutePos(new BlockPos(x,y,z)),GoetiaFluids.BLOCK.get().defaultBlockState());
 }
 var a=h.absolutePos(new BlockPos(3,2,3));
 var cow=net.minecraft.world.entity.EntityTypes.COW.create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);cow.setNoAi(true);cow.setNoGravity(true);cow.setPos(a.getX()+.5,a.getY(),a.getZ()+.5);
 cow.setAirSupply(100);cow.igniteForSeconds(10);cow.fallDistance=17;
 cow.baseTick();
 h.assertTrue(cow.isInWater()&&cow.isInWaterOrRain(),"holy water preserves material-water wet queries");
 h.assertTrue(cow.getFluidHeight(net.minecraft.tags.FluidTags.WATER)>0,"water-height query includes custom fluid");
 h.assertTrue(cow.isEyeInFluid(net.minecraft.tags.FluidTags.WATER),"water eye query includes custom fluid");
 h.assertTrue(cow.getAirSupply()<100,"ordinary land mob uses actual engine breathing consumption");
 h.assertTrue(cow.getRemainingFireTicks()<=0,"holy water clears fire before burning damage: ticks="+cow.getRemainingFireTicks());h.assertTrue(cow.fallDistance==0,"native water-like update resets falls: distance="+cow.fallDistance);h.assertTrue(cow.getHealth()==cow.getMaxHealth(),"early wet phase prevents initial fire damage: health="+cow.getHealth());
 cow.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.WATER_BREATHING,100));
 cow.setAirSupply(100);cow.baseTick();h.assertTrue(cow.getAirSupply()==100,"water-breathing effect prevents consumption");
 var squid=net.minecraft.world.entity.EntityTypes.SQUID.create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);squid.setNoAi(true);squid.setNoGravity(true);squid.setPos(a.getX()+.5,a.getY(),a.getZ()+.5);squid.setAirSupply(100);squid.baseTick();
 h.assertTrue(squid.canBreatheUnderwater()&&squid.getAirSupply()>=100,"water-breathing mob exemption survives custom FluidType");
 var wet=GoetiaEntities.DEMONS.get(0).get().create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);wet.setNoAi(true);wet.setNoGravity(true);wet.setPos(a.getX()+.5,a.getY(),a.getZ()+.5);wet.setHealth(.5F);wet.holyWater();wet.tick();h.assertTrue(wet.isAlive()&&Math.abs(wet.getHealth()-.5F)<1e-6,"low-health immersed demon survives fire before late block effects");
 var dryAt=h.absolutePos(new BlockPos(6,2,6));var dry=GoetiaEntities.DEMONS.get(0).get().create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);dry.setNoAi(true);dry.setNoGravity(true);dry.setPos(dryAt.getX()+.5,dryAt.getY(),dryAt.getZ()+.5);dry.holyWater();dry.tick();h.assertTrue(dry.isOnFire()&&!dry.fireImmune()&&dry.getHealth()<dry.getMaxHealth(),"dry holy-water effect still burns and damages demons");

 h.succeed();
}


 private static final class TickProbe extends FakePlayer {
  int timerAtMovement;net.minecraft.world.phys.Vec3 motionAtMovement;
  TickProbe(net.minecraft.server.level.ServerLevel level){super(level,new GameProfile(UUID.randomUUID(),"TickProbe"));}
  @Override public void aiStep(){timerAtMovement=GoetiaPlayer.data(this).getIntOr("inner_fire_grace",0);motionAtMovement=getDeltaMovement();}
 }
 public static void effectTicksBeforeMovementExactlyOnce(GameTestHelper h){var p=new TickProbe(h.getLevel());var at=h.absolutePos(new BlockPos(3,3,3));p.setPos(at.getX(),at.getY(),at.getZ());p.setOnGround(true);p.setDeltaMovement(.2,0,.3);GoetiaPlayer.data(p).putInt("inner_fire_grace",2);p.doTick();h.assertTrue(p.timerAtMovement==1&&Math.abs(p.motionAtMovement.x-.28)<1e-8&&Math.abs(p.motionAtMovement.z-.42)<1e-8,"timer and1.4 motion apply once before movement");p.setOnGround(true);p.setDeltaMovement(.2,0,.3);p.doTick();h.assertTrue(p.timerAtMovement==0&&Math.abs(p.motionAtMovement.x-.2)<1e-8,"expired timer is removed before movement");h.succeed();}
 public static void alignmentThresholdIsCapturedPerPlayer(GameTestHelper h){int saved=GoetiaConfig.THRESHOLD.get();try{GoetiaConfig.THRESHOLD.set(1000);var old=player(h);GoetiaPlayer.set(old,"impurity",750);GoetiaConfig.THRESHOLD.set(500);var fresh=player(h);GoetiaPlayer.set(fresh,"impurity",750);h.assertTrue(GoetiaPlayer.alignment(old)==GoetiaPlayer.Alignment.HUMAN&&GoetiaPlayer.alignment(fresh)==GoetiaPlayer.Alignment.DEMON,"existing player retains captured threshold while new player captures reload");}finally{GoetiaConfig.THRESHOLD.set(saved);}h.succeed();}

 private static net.minecraft.nbt.CompoundTag saveEntity(net.minecraft.world.entity.Entity entity){var out=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,entity.level().registryAccess());entity.save(out);return out.buildResult();}
 private static void loadEntity(net.minecraft.world.entity.Entity entity,net.minecraft.nbt.CompoundTag tag){entity.load(net.minecraft.world.level.storage.TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,entity.level().registryAccess(),tag));}

 public static void releasedFireballsImpactDeflectingMobs(GameTestHelper h){
  var w=h.getLevel();var at=h.absolutePos(new BlockPos(3,3,3));var breeze=net.minecraft.world.entity.EntityTypes.BREEZE.create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);breeze.setNoAi(true);breeze.setNoGravity(true);breeze.setPos(at.getX()+2.5,at.getY(),at.getZ()+.5);w.addFreshEntity(breeze);
  var ordinary=net.minecraft.world.entity.EntityTypes.FIREBALL.create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);ordinary.setPos(at.getX()+.5,at.getY()+.5,at.getZ()+.5);ordinary.setDeltaMovement(3,0,0);h.assertTrue(breeze.deflection(ordinary)!=net.minecraft.world.entity.projectile.ProjectileDeflection.NONE,"native target actually deflects this projectile");ordinary.tick();h.assertTrue(!ordinary.isRemoved()&&ordinary.getDeltaMovement().x<0,"unmarked native fireball still deflects");ordinary.discard();
  var released=net.minecraft.world.entity.EntityTypes.FIREBALL.create(w,net.minecraft.world.entity.EntitySpawnReason.TRIGGERED);GoetiaFireballs.start(released,new net.minecraft.world.phys.Vec3(1,0,0));released.setPos(at.getX()+.5,at.getY()+.5,at.getZ()+.5);released.setDeltaMovement(3,0,0);released.tick();h.assertTrue(released.isRemoved(),"marked fireball invokes the released direct impact instead of modern mob deflection");breeze.discard();h.succeed();
 }
}
